function marcarNovo(){
  $('dicaTel').hidden = true;
  jaConfirmado = false;
  $('tituloForm').textContent = 'Confirme sua presença';
  atualizarTrava();
}

async function consultar(telefone){
  try{
    const r = await api('consultar', { telefone });
    if(r.registro){
      /* Mostra o que está gravado, mas travado: mudança só via organização. */
      $('nome').value = r.registro.nome || '';
      $('combo').value = COMBOS[r.registro.combo] ? r.registro.combo : 'feijoada';
      deps = (r.registro.dependentes || []).map(d=>({ nome:d.nome, tipo:d.tipo, combo:d.combo }));
      $('recado').value = r.registro.recado || '';
      $('dicaTel').hidden = false;
      jaConfirmado = true;
      $('tituloForm').textContent = 'Sua presença já está confirmada';
      renderDeps();
    } else {
      marcarNovo();
    }
    aplicar(r);
  }catch(err){ /* consulta é conveniência: falha não bloqueia o envio */ }
}

